    /**
     * Handles create a Order.  if not key provided, calls create, otherwise calls save
     * @param		Order	order
     * @return		Order 
     */
	@PostMapping("/create")
    public Order create( @RequestBody(required=true) CreateOrderCommand command ) {
    	Order entity = null;
		try {       
        	
			entity = OrderBusinessDelegate.getOrderInstance().createOrder( command );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage(), exc );        	
        }
		
		return entity;
    }

    /**
     * Handles updating a Order.  if no key provided, calls create, otherwise calls save
     * @param		Order order
     * @return		Order
     */
	@PutMapping("/update")
    public Order update( @RequestBody(required=true) UpdateOrderCommand command ) {
		Order entity = null;
		try {                        	        
			// -----------------------------------------------
			// delegate the UpdateOrderCommand
			// -----------------------------------------------
			entity = OrderBusinessDelegate.getOrderInstance().updateOrder(command);;
	    }
	    catch( Throwable exc ) {
	    	LOGGER.log( Level.WARNING, "OrderController:update() - successfully update Order - " + exc.getMessage());        	
	    }		
		
		return entity;
	}
 
    /**
     * Handles deleting a Order entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteOrderCommand command ) {                
    	try {
        	OrderBusinessDelegate delegate = OrderBusinessDelegate.getOrderInstance();

        	delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Order with key " + command.getOrderId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }

	}        
	
    /**
     * Handles loading a Order using a UUID
     * @param		UUID uuid 
     * @return		Order
     */    
    @GetMapping("/load")
    public Order load( @RequestParam(required=true) UUID uuid ) {    	
    	Order entity = null;

    	try {  
    		entity = OrderBusinessDelegate.getOrderInstance().getOrder( new OrderFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Order using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Order business objects
     * @return		Set<Order>
     */
    @GetMapping("/")
    public List<Order> loadAll() {                
    	List<Order> orderList = null;
        
    	try {
            // load the Order
            orderList = OrderBusinessDelegate.getOrderInstance().getAllOrder();
            
            if ( orderList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Orders" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Orders ", exc );
        	return null;
        }

        return orderList;
                            
    }

